/// Returns an index of a minimum element in the half-open range [from, to).
/// Preconditions (as stated): 0 <= from < to <= a.len().
/// If there are multiple minima, any one of them may be returned.
fn find_min(a: &mut [i32], from: usize, to: usize) -> usize {
    debug_assert!(from < to);
    debug_assert!(to <= a.len());

    let mut min_idx = from;
    for i in (from + 1)..to {
        if a[i] < a[min_idx] {
            min_idx = i;
        }
    }
    min_idx
}

fn main() {
    let mut a = [3, 1, 2, 1, 5];
    let idx = find_min(&mut a, 1, 4); // range is [1,4) -> values [1,2,1]
    println!("min index = {}, min value = {}", idx, a[idx]);
}